<?php namespace App\Controllers; use App\Models\InvoiceModel;use App\Models\InvoiceItemModel;use App\Models\InvoicePaymentModel;use App\Models\UserModel;use CodeIgniter\Controller;use Dompdf\Dompdf;use Dompdf\Options;
class Invoice extends Controller {protected $invoices,$items,$payments;public function __construct(){$this->invoices=new InvoiceModel;$this->items=new InvoiceItemModel;$this->payments=new InvoicePaymentModel;}public function index(){$q=trim((string)$this->request->getGet('q'));$status=strtoupper(trim((string)$this->request->getGet('status')));$b=$this->invoices->orderBy('id','DESC');if($q)$b->groupStart()->like('invoice_no',$q)->orLike('client_name',$q)->orLike('case_reference',$q)->groupEnd();if(in_array($status,['UNPAID','PARTIAL','PAID'],true))$b->where('payment_status',$status);return view('invoices/index',['title'=>'Invoices','invoices'=>$b->findAll(),'q'=>$q,'status'=>$status]);}public function create(){return view('invoices/form',['title'=>'Create Invoice','users'=>(new UserModel)->where('role','user')->where('status','active')->orderBy('name')->findAll()]);}public function store(){$ds=$this->request->getPost('description')??[];$qs=$this->request->getPost('quantity')??[];$rs=$this->request->getPost('rate')??[];$ms=$this->request->getPost('manual_amount')??[];$flat=(bool)$this->request->getPost('flat_mode');$rows=[];$sub=0;foreach((array)$ds as $i=>$d){$d=trim((string)$d);if($d==='')continue;$q=(float)($qs[$i]??1);$r=(float)($rs[$i]??0);$m=(float)($ms[$i]??0);if($flat){$q=1;$r=0;if($m<0)return redirect()->back()->withInput()->with('error','Manual amount cannot be negative.');$a=round($m,2);}else{if($q<=0||$r<0)return redirect()->back()->withInput()->with('error','Quantity must be > 0 and rate cannot be negative.');$a=round($q*$r,2);} $rows[]=['description'=>$d,'quantity'=>$q,'rate'=>$r,'amount'=>$a,'sort_order'=>count($rows)];$sub+=$a;}if(!$rows)return redirect()->back()->withInput()->with('error','Add at least one professional charge line.');$adj=(float)($this->request->getPost('adjustment')??0);$tax=(float)($this->request->getPost('tax_amount')??0);$total=round($sub+$adj+$tax,2);$uid=(int)($this->request->getPost('user_id')??0);$u=$uid?(new UserModel)->find($uid):null;$no=trim((string)$this->request->getPost('invoice_no'))?:$this->nextNo();$d=['invoice_no'=>$no,'invoice_date'=>$this->request->getPost('invoice_date')?:date('Y-m-d'),'due_date'=>$this->request->getPost('due_date')?:null,'user_id'=>$uid?:null,'client_name'=>trim((string)($this->request->getPost('client_name')?:($u['name']??''))),'client_address'=>trim((string)$this->request->getPost('client_address')),'client_email'=>trim((string)($this->request->getPost('client_email')?:($u['email']??''))),'client_phone'=>trim((string)$this->request->getPost('client_phone')),'case_reference'=>trim((string)$this->request->getPost('case_reference')),'advocate_name'=>trim((string)($this->request->getPost('advocate_name')?:'Ankit Gupta')),'narration'=>trim((string)$this->request->getPost('narration')),'subtotal'=>$sub,'adjustment'=>$adj,'tax_amount'=>$tax,'total'=>$total,'amount_words'=>$this->words($total),'payment_status'=>'UNPAID','notes'=>trim((string)$this->request->getPost('notes')),'bank_name'=>trim((string)($this->request->getPost('bank_name')?:'Indian Bank')),'bank_account'=>trim((string)($this->request->getPost('bank_account')?:'7592639814')),'bank_branch'=>trim((string)($this->request->getPost('bank_branch')?:'kanganheri (New Delhi)')),'bank_ifsc'=>trim((string)($this->request->getPost('bank_ifsc')?:'IDIB000K568')),'pan'=>trim((string)($this->request->getPost('pan')?:'BNEPG8812Q')),'created_by'=>(int)session()->get('user_id')];try{$id=$this->invoices->insert($d,true);foreach($rows as $r){$r['invoice_id']=$id;$this->items->insert($r);}return redirect()->to(site_url('admin/invoices/'.$id))->with('success','Invoice created successfully.');}catch(\Throwable $e){return redirect()->back()->withInput()->with('error',$e->getMessage());}}public function show($id){$i=$this->invoices->find($id);if(!$i)return redirect()->to('admin/invoices')->with('error','Invoice not found.');return view('invoices/show',['title'=>'Invoice '.$i['invoice_no'],'invoice'=>$i,'items'=>$this->items->where('invoice_id',$id)->orderBy('sort_order')->findAll(),'payments'=>$this->payments->where('invoice_id',$id)->orderBy('payment_date','DESC')->findAll(),'paid'=>$this->paid($id)]);}public function addPayment($id){$i=$this->invoices->find($id);if(!$i)return redirect()->to('admin/invoices');$a=(float)$this->request->getPost('amount');$remain=round((float)$i['total']-$this->paid($id),2);if($a<=0||$a>$remain)return redirect()->back()->with('error','Invalid payment amount or payment exceeds outstanding balance.');$this->payments->insert(['invoice_id'=>$id,'payment_date'=>$this->request->getPost('payment_date')?:date('Y-m-d'),'amount'=>$a,'method'=>trim((string)$this->request->getPost('method'))?:'Online/Wire Transfer','reference_no'=>trim((string)$this->request->getPost('reference_no'))?:null,'notes'=>trim((string)$this->request->getPost('notes'))?:null,'created_by'=>(int)session()->get('user_id')]);$p=$this->paid($id);$this->invoices->update($id,['payment_status'=>$p+0.001>=(float)$i['total']?'PAID':'PARTIAL']);return redirect()->to(site_url('admin/invoices/'.$id))->with('success','Payment recorded.');}public function print($id){return $this->render($id,false);}public function pdf($id){return $this->render($id,true);}public function userIndex(){$rows=$this->invoices->where('user_id',(int)session()->get('user_id'))->orderBy('id','DESC')->findAll();return view('user/invoices',['title'=>'My Invoices','invoices'=>$rows]);}public function userShow($id){$i=$this->invoices->where('user_id',(int)session()->get('user_id'))->find($id);if(!$i)return redirect()->to('dashboard')->with('error','Invoice not found.');return view('invoices/show_user',['title'=>'Invoice '.$i['invoice_no'],'invoice'=>$i,'items'=>$this->items->where('invoice_id',$id)->orderBy('sort_order')->findAll(),'paid'=>$this->paid($id)]);}public function userPrint($id){$i=$this->invoices->where('user_id',(int)session()->get('user_id'))->find($id);if(!$i)return redirect()->to('dashboard');return $this->render($id,false);}protected function render($id,$pdf){$i=$this->invoices->find($id);if(!$i)return redirect()->to('admin/invoices');$html=view('invoices/print',['invoice'=>$i,'items'=>$this->items->where('invoice_id',$id)->orderBy('sort_order')->findAll()]);if(!$pdf)return $html;$o=new Options;$o->set('isRemoteEnabled',true);$o->set('defaultFont','DejaVu Sans');$d=new Dompdf($o);$d->loadHtml($html);$d->setPaper('A4','portrait');$d->render();return $this->response->download($i['invoice_no'].'.pdf',$d->output());}protected function paid($id){$r=$this->payments->selectSum('amount')->where('invoice_id',$id)->first();return round((float)($r['amount']??0),2);}protected function nextNo(){$y=(int)date('Y');$fy=date('m')>=4?$y.'-'.substr((string)($y+1),-2):($y-1).'-'.substr((string)$y,-2);$l=$this->invoices->like('invoice_no',$fy.'/LFP/','after')->orderBy('id','DESC')->first();$n=1;if($l&&preg_match('/\/(\d+)$/',$l['invoice_no'],$m))$n=(int)$m[1]+1;return $fy.'/LFP/'.str_pad((string)$n,2,'0',STR_PAD_LEFT);}protected function words($n){$n=(int)round($n);if(!$n)return 'Zero Only';$o=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];$t=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];$c=function($x)use(&$c,$o,$t){$s='';if($x>=100){$s.=$o[intdiv($x,100)].' Hundred ';$x%=100;}if($x>=20){$s.=$t[intdiv($x,10)].' ';$x%=10;}if($x)$s.=$o[$x].' ';return trim($s);};$p=[];if($n>=10000000){$p[]=$c(intdiv($n,10000000)).' Crore';$n%=10000000;}if($n>=100000){$p[]=$c(intdiv($n,100000)).' Lakh';$n%=100000;}if($n>=1000){$p[]=$c(intdiv($n,1000)).' Thousand';$n%=1000;}if($n)$p[]=$c($n);return implode(' ',array_filter($p)).' Only';}}
